/* Verse Games: THE WHOLE COUNSEL · 1 Chronicles chapters 21-25
   Verse text is filled/verified from the KJV by tools/fill-verses.js */
VG.registerBibleChapters("1chronicles", [
{n:21, name:"The Census and the Plague",
 seal:{ref:"1 Chronicles 21:13",verse:"And David said unto Gad, I am in a great strait: let me fall now into the hand of the LORD; for very great are his mercies: but let me not fall into the hand of man."},
 facts:[
  "Did you know the threshingfloor David bought from Ornan for six hundred shekels of gold became the site of the temple? David's next words point straight at it: 'This is the house of the LORD God' (1 Chronicles 21:25; 22:1).",
  "Did you know David refused Ornan's free gift with words every giver should remember: 'I will not take that which is thine for the LORD, nor offer burnt offerings without cost' (1 Chronicles 21:24)?",
  "Did you know God answered David's altar sacrifice with fire from heaven, the same sign that would later mark the temple's dedication (1 Chronicles 21:26)?"
 ],
 questions:[
{q:"Who provoked David to number Israel?", options:["Satan","Joab the captain of the host","Gad the seer","Abishai the son of Zeruiah"], a:0, ref:"1 Chronicles 21:1",verse:"And Satan stood up against Israel, and provoked David to number Israel.", insight:"The provocation came from the adversary; not every strong urge to measure yourself is from God."},
{q:"From where to where was the census to run?", options:["From Beer-sheba even to Dan","From Jerusalem even to Gibeon","From the Red Sea even to the Euphrates","From Hebron even to Beersheba"], a:0, ref:"1 Chronicles 21:2",verse:"And David said to Joab and to the rulers of the people, Go, number Israel from Beer-sheba even to Dan; and bring the number of them to me, that I may know it.", insight:"Beer-sheba to Dan meant the whole nation; David wanted the full measure of his own strength."},
{q:"How many men of Israel drew the sword?", options:["A thousand thousand and an hundred thousand","Four hundred threescore and ten thousand","Seventy thousand","Three hundred thousand"], a:0, ref:"1 Chronicles 21:5",verse:"And Joab gave the sum of the number of the people unto David. And all they of Israel were a thousand thousand and an hundred thousand men that drew sword: and Judah was four hundred threescore and ten thousand men that drew sword.", insight:"Eleven hundred thousand swords; David had wanted the number, and the number would cost him dearly."},
{q:"How many men of Judah drew the sword?", options:["Four hundred threescore and ten thousand","A thousand thousand and an hundred thousand","Six hundred thousand","Seventy thousand"], a:0, ref:"1 Chronicles 21:5",verse:"And Joab gave the sum of the number of the people unto David. And all they of Israel were a thousand thousand and an hundred thousand men that drew sword: and Judah was four hundred threescore and ten thousand men that drew sword.", insight:"Judah's number is counted apart, as always; the tribe of the promise keeps its own reckoning."},
{q:"Which two tribes did Joab refuse to count?", options:["Levi and Benjamin","Judah and Simeon","Ephraim and Manasseh","Gad and Reuben"], a:0, ref:"1 Chronicles 21:6",verse:"But Levi and Benjamin counted he not among them: for the king’s word was abominable to Joab.", insight:"Even Joab drew a line at Levi and Benjamin; conscience is not dead when it still limits obedience."},
{q:"How did God respond to the numbering?", options:["God was displeased with this thing; therefore he smote Israel","God was pleased with the numbering","God ignored the census entirely","God blessed David for his diligence"], a:0, ref:"1 Chronicles 21:7",verse:"And God was displeased with this thing; therefore he smote Israel.", insight:"God was displeased with this thing; pride in our numbers displeases Him still."},
{q:"What did David confess to God?", options:["I have sinned greatly, for I have done very foolishly","The people forced my hand","Joab is to blame for the count","The census was a wise decision"], a:0, ref:"1 Chronicles 21:8",verse:"And David said unto God, I have sinned greatly, because I have done this thing: but now, I beseech thee, do away the iniquity of thy servant; for I have done very foolishly.", insight:"'I have done very foolishly'; true confession names the sin and owns the folly."},
{q:"Through whom did the LORD speak to David?", options:["Gad, David's seer","Nathan the prophet","Zadok the priest","Abiathar the priest"], a:0, ref:"1 Chronicles 21:9",verse:"And the LORD spake unto Gad, David’s seer, saying,", insight:"God spoke through Gad, David's seer; He keeps a voice near the throne, if the king will hear it."},
{q:"Which three punishments were set before David?", options:["Three years' famine, three months before foes, or three days' pestilence","Three years of war, three months of famine, three days of darkness","Flood, fire, and earthquake","Exile, slavery, or death"], a:0, ref:"1 Chronicles 21:12",verse:"Either three years’ famine; or three months to be destroyed before thy foes, while that the sword of thine enemies overtaketh thee; or else three days the sword of the LORD, even the pestilence, in the land, and the angel of the LORD destroying throughout all the coasts of Israel. Now therefore advise thyself what word I shall bring again to him that sent me.", insight:"Famine, sword, or pestilence; every choice was bitter, for sin's wages are never sweet."},
{q:"Which judgment did David choose?", options:["To fall into the hand of the LORD, and not into the hand of man","Three years of famine","Three months destroyed before his foes","No judgment at all"], a:0, ref:"1 Chronicles 21:13",verse:"And David said unto Gad, I am in a great strait: let me fall now into the hand of the LORD; for very great are his mercies: but let me not fall into the hand of man.", insight:"'Let me fall now into the hand of the LORD'; when judgment is certain, choose the Judge whose mercies are great."},
{q:"How many men of Israel fell in the pestilence?", options:["Seventy thousand men","Seven thousand men","Three thousand men","Forty thousand men"], a:0, ref:"1 Chronicles 21:14",verse:"So the LORD sent pestilence upon Israel: and there fell of Israel seventy thousand men.", insight:"Seventy thousand fell for one man's census; a leader's sin is never a private affair."},
{q:"Where did the destroying angel halt?", options:["By the threshingfloor of Ornan the Jebusite","At the gates of Jerusalem","Upon the mount of Olives","In the valley of Hinnom"], a:0, ref:"1 Chronicles 21:15",verse:"And God sent an angel unto Jerusalem to destroy it: and as he was destroying, the LORD beheld, and he repented him of the evil, and said to the angel that destroyed, It is enough, stay now thine hand. And the angel of the LORD stood by the threshingfloor of Ornan the Jebusite.", insight:"The angel stopped at a Jebusite's threshingfloor; mercy found its footing on common ground."},
{q:"What did David see standing between earth and heaven?", options:["The angel of the LORD with a drawn sword stretched out over Jerusalem","A pillar of fire","A host of chariots","A bright cloud"], a:0, ref:"1 Chronicles 21:16",verse:"And David lifted up his eyes, and saw the angel of the LORD stand between the earth and the heaven, having a drawn sword in his hand stretched out over Jerusalem. Then David and the elders of Israel, who were clothed in sackcloth, fell upon their faces.", insight:"A drawn sword over Jerusalem; judgment is real, and it hangs over real cities."},
{q:"What did David plead with God?", options:["Let thine hand be on me and my father's house, but not on thy people","Spare Jerusalem only","Take Joab's life instead","Send the plague upon the Philistines"], a:0, ref:"1 Chronicles 21:17",verse:"And David said unto God, Is it not I that commanded the people to be numbered? even I it is that have sinned and done evil indeed; but as for these sheep, what have they done? let thine hand, I pray thee, O LORD my God, be on me, and on my father’s house; but not on thy people, that they should be plagued.", insight:"'But as for these sheep, what have they done?' The shepherd's heart asks to bear the blow himself."},
{q:"What was David commanded to do at Ornan's threshingfloor?", options:["Set up an altar unto the LORD there","Flee to Gibeon","Offer a thousand rams","Rebuild the tabernacle"], a:0, ref:"1 Chronicles 21:18",verse:"Then the angel of the LORD commanded Gad to say to David, that David should go up, and set up an altar unto the LORD in the threshingfloor of Ornan the Jebusite.", insight:"An altar on the threshingfloor; the place of judgment becomes the place of mercy."},
{q:"Why would David not accept the gift of the threshingfloor?", options:["I will not take that which is thine for the LORD, nor offer burnt offerings without cost","He distrusted Ornan's motives","He had no need of the oxen","The law forbade such gifts"], a:0, ref:"1 Chronicles 21:24",verse:"And king David said to Ornan, Nay; but I will verily buy it for the full price: for I will not take that which is thine for the LORD, nor offer burnt offerings without cost.", insight:"Costless offerings cost the giver nothing and gain him nothing; David knew the difference."},
{q:"How much did David pay Ornan for the place?", options:["Six hundred shekels of gold by weight","Fifty shekels of silver","Three thousand talents of brass","Six hundred talents of iron"], a:0, ref:"1 Chronicles 21:25",verse:"So David gave to Ornan for the place six hundred shekels of gold by weight.", insight:"Six hundred shekels of gold; repentance paid in full, weighed out honestly."},
{q:"How did the LORD answer David's sacrifice?", options:["By fire upon the altar of burnt offering","With thunder from a clear sky","Through Gad the seer","With rain after the drought"], a:0, ref:"1 Chronicles 21:26",verse:"And David built there an altar unto the LORD, and offered burnt offerings and peace offerings, and called upon the LORD; and he answered him from heaven by fire upon the altar of burnt offering.", insight:"Fire fell from heaven on the altar; God seals true repentance with His own flame."},
{q:"Where was the tabernacle of Moses at that season?", options:["In the high place at Gibeon","In Jerusalem","In Shiloh","In Hebron"], a:0, ref:"1 Chronicles 21:29",verse:"For the tabernacle of the LORD, which Moses made in the wilderness, and the altar of the burnt offering, were at that season in the high place at Gibeon.", insight:"The old tabernacle still stood at Gibeon; God was already moving the center to Jerusalem."},
{q:"Why could David not go to Gibeon to enquire of God?", options:["He was afraid because of the sword of the angel of the LORD","The road was too long","The priests refused him entry","The tabernacle was closed"], a:0, ref:"1 Chronicles 21:30",verse:"But David could not go before it to enquire of God: for he was afraid because of the sword of the angel of the LORD.", insight:"Fear of the angel's sword kept him from Gibeon; awe is a poor traveler but an honest one."}
 ]},
{n:22, name:"Preparing for the Temple",
 seal:{ref:"1 Chronicles 22:19",verse:"Now set your heart and your soul to seek the LORD your God; arise therefore, and build ye the sanctuary of the LORD God, to bring the ark of the covenant of the LORD, and the holy vessels of God, into the house that is to be built to the name of the LORD."},
 facts:[
  "Did you know David stockpiled one hundred thousand talents of gold and a million talents of silver for the temple, and he calls it preparation 'in my trouble,' giving out of his affliction years (1 Chronicles 22:14)?",
  "Did you know Solomon's very name is a promise? God said, 'his name shall be Solomon, and I will give peace and quietness unto Israel in his days' (1 Chronicles 22:9).",
  "Did you know David the warrior accepted he could not build God's house because he had 'shed blood abundantly'? The temple would rise under a man of rest, not a man of war (1 Chronicles 22:8-9)."
 ],
 questions:[
{q:"What did David declare about the threshingfloor he had bought?", options:["This is the house of the LORD God, and this is the altar of the burnt offering for Israel","This is the palace of the king","This is the gate of the city","This is the field of the Jebusites"], a:0, ref:"1 Chronicles 22:1",verse:"Then David said, This is the house of the LORD God, and this is the altar of the burnt offering for Israel.", insight:"A threshingfloor became the house of God; the ground of judgment became the ground of worship."},
{q:"Whom did David gather to build the house of God?", options:["The strangers in the land of Israel, and he set masons to hew wrought stones","The armies of Judah","The elders of Gibeon","The merchants of Tyre"], a:0, ref:"1 Chronicles 22:2",verse:"And David commanded to gather together the strangers that were in the land of Israel; and he set masons to hew wrought stones to build the house of God.", insight:"Strangers hewed the stones; God uses outsiders' hands in His own house."},
{q:"What did David prepare in abundance for the temple?", options:["Iron for the nails and joinings, and brass without weight","Gold for the vessels","Silver for the trumpets","Timber for the rafters"], a:0, ref:"1 Chronicles 22:3",verse:"And David prepared iron in abundance for the nails for the doors of the gates, and for the joinings; and brass in abundance without weight;", insight:"Iron and brass without weight; David's generosity had no scale big enough."},
{q:"Who brought much cedar wood to David?", options:["The Zidonians and they of Tyre","The Egyptians","The men of Gibeon","The Philistines"], a:0, ref:"1 Chronicles 22:4",verse:"Also cedar trees in abundance: for the Zidonians and they of Tyre brought much cedar wood to David.", insight:"Cedar from Zidon and Tyre; even Gentile kings supplied timber for God's house."},
{q:"Why did David make preparation before his death?", options:["Solomon was young and tender, and the house must be exceeding magnifical","The old tabernacle had burned down","The people demanded a temple","The ark had been lost"], a:0, ref:"1 Chronicles 22:5",verse:"And David said, Solomon my son is young and tender, and the house that is to be builded for the LORD must be exceeding magnifical, of fame and of glory throughout all countries: I will therefore now make preparation for it. So David prepared abundantly before his death.", insight:"'Exceeding magnifical, of fame and of glory'; small visions do not build for God."},
{q:"What charge did David give to Solomon his son?", options:["To build an house for the LORD God of Israel","To number the people again","To make war on the Philistines","To rebuild the walls of Jerusalem"], a:0, ref:"1 Chronicles 22:6",verse:"Then he called for Solomon his son, and charged him to build an house for the LORD God of Israel.", insight:"The father's charge to the son; the greatest inheritance is a God-given task."},
{q:"What had been in David's own mind?", options:["To build an house unto the name of the LORD his God","To enlarge his palace","To conquer the surrounding nations","To retire to Hebron"], a:0, ref:"1 Chronicles 22:7",verse:"And David said to Solomon, My son, as for me, it was in my mind to build an house unto the name of the LORD my God:", insight:"It was in his mind to build; God honors the desire even when He redirects the doer."},
{q:"Why would David not build the house?", options:["He had shed blood abundantly and made great wars","He was too old for the work","He lacked the materials","The people opposed the plan"], a:0, ref:"1 Chronicles 22:8",verse:"But the word of the LORD came to me, saying, Thou hast shed blood abundantly, and hast made great wars: thou shalt not build an house unto my name, because thou hast shed much blood upon the earth in my sight.", insight:"Much blood on his hands; the house of peace could not rise by the man of war."},
{q:"What kind of man would David's son be?", options:["A man of rest","A man of war","A man of wealth","A man of learning"], a:0, ref:"1 Chronicles 22:9",verse:"Behold, a son shall be born to thee, who shall be a man of rest; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness unto Israel in his days.", insight:"A man of rest; God's house is built in peace, not in strife."},
{q:"What did God promise to give Israel in Solomon's days?", options:["Peace and quietness","Riches and honor","Victory in every battle","Rain in due season"], a:0, ref:"1 Chronicles 22:9",verse:"Behold, a son shall be born to thee, who shall be a man of rest; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness unto Israel in his days.", insight:"Peace and quietness; the best gift a king can give his people is rest from war."},
{q:"What did God promise about the son who would build?", options:["He shall be my son, and I will be his father","He shall be a prophet to the nations","He shall never die","He shall rule the whole earth"], a:0, ref:"1 Chronicles 22:10",verse:"He shall build an house for my name; and he shall be my son, and I will be his father; and I will establish the throne of his kingdom over Israel for ever.", insight:"'He shall be my son'; the builder of God's house works as God's own child."},
{q:"What did David pray over Solomon?", options:["The LORD be with thee; and prosper thou","The LORD give thee long life","The LORD make thee a warrior","The LORD hide thee from enemies"], a:0, ref:"1 Chronicles 22:11",verse:"Now, my son, the LORD be with thee; and prosper thou, and build the house of the LORD thy God, as he hath said of thee.", insight:"'The LORD be with thee'; no better prayer was ever prayed over a young leader."},
{q:"What two gifts did David ask God to give Solomon?", options:["Wisdom and understanding","Riches and honor","Strength and courage","Sons and daughters"], a:0, ref:"1 Chronicles 22:12",verse:"Only the LORD give thee wisdom and understanding, and give thee charge concerning Israel, that thou mayest keep the law of the LORD thy God.", insight:"Wisdom and understanding before gold; David knew what a king needs most."},
{q:"On what condition would Solomon prosper?", options:["If he took heed to fulfil the statutes and judgments of the LORD","If he built the largest army","If he married foreign princesses","If he stored up gold"], a:0, ref:"1 Chronicles 22:13",verse:"Then shalt thou prosper, if thou takest heed to fulfil the statutes and judgments which the LORD charged Moses with concerning Israel: be strong, and of good courage; dread not, nor be dismayed.", insight:"Prosperity follows obedience; 'be strong, and of good courage' is the charge, not 'be clever.'"},
{q:"How much gold had David prepared for the house of the LORD?", options:["An hundred thousand talents of gold","Ten thousand talents","A thousand talents","A million talents"], a:0, ref:"1 Chronicles 22:14",verse:"Now, behold, in my trouble I have prepared for the house of the LORD an hundred thousand talents of gold, and a thousand thousand talents of silver; and of brass and iron without weight; for it is in abundance: timber also and stone have I prepared; and thou mayest add thereto.", insight:"A hundred thousand talents of gold, gathered 'in my trouble'; affliction can stockpile generosity."},
{q:"How much silver had David prepared?", options:["A thousand thousand talents of silver","An hundred thousand talents","Ten thousand talents","Brass without weight"], a:0, ref:"1 Chronicles 22:14",verse:"Now, behold, in my trouble I have prepared for the house of the LORD an hundred thousand talents of gold, and a thousand thousand talents of silver; and of brass and iron without weight; for it is in abundance: timber also and stone have I prepared; and thou mayest add thereto.", insight:"A million talents of silver; David gave for God's house on a scale his wars never matched."},
{q:"What workmen would serve Solomon?", options:["Hewers and workers of stone and timber, and cunning men for every manner of work","Only the priests","Only the Levites","Foreign slaves alone"], a:0, ref:"1 Chronicles 22:15",verse:"Moreover there are workmen with thee in abundance, hewers and workers of stone and timber, and all manner of cunning men for every manner of work.", insight:"Cunning men for every manner of work; God staffs His house with skilled hands."},
{q:"Whom did David command to help Solomon?", options:["All the princes of Israel","The captains of the army","The elders of Judah only","The sons of Aaron"], a:0, ref:"1 Chronicles 22:17",verse:"David also commanded all the princes of Israel to help Solomon his son, saying,", insight:"All the princes to help the young king; great works need united leaders."},
{q:"What was David's final charge to the princes?", options:["Set your heart and your soul to seek the LORD your God; arise and build the sanctuary","Guard the borders of Israel","Number the fighting men","Enlarge the palace"], a:0, ref:"1 Chronicles 22:19",verse:"Now set your heart and your soul to seek the LORD your God; arise therefore, and build ye the sanctuary of the LORD God, to bring the ark of the covenant of the LORD, and the holy vessels of God, into the house that is to be built to the name of the LORD.", insight:"Seek first, then build; the sanctuary rises only from seeking hearts."},
{q:"What reason did David give for building the house now?", options:["The LORD had given them rest and subdued the land","The Philistines demanded it","Solomon had come of age","The tabernacle was decaying"], a:0, ref:"1 Chronicles 22:18",verse:"Is not the LORD your God with you? and hath he not given you rest on every side? for he hath given the inhabitants of the land into mine hand; and the land is subdued before the LORD, and before his people.", insight:"Rest is the season for building; David used peace to prepare God's house."}
 ]},
{n:23, name:"The Levites Numbered",
 seal:{ref:"1 Chronicles 23:30",verse:"And to stand every morning to thank and praise the LORD, and likewise at even;"},
 facts:[
  "Did you know the Levites' service age dropped from thirty to twenty by 'the last words of David,' because they no longer had to carry the tabernacle now that God had given Israel rest (1 Chronicles 23:26-27)?",
  "Did you know four thousand Levites were set apart to do nothing but praise the LORD with instruments David himself had made (1 Chronicles 23:5)?",
  "Did you know the Levites' daily task was simply to stand every morning and evening to thank and praise the LORD (1 Chronicles 23:30)?"
 ],
 questions:[
{q:"What did David do when he was old and full of days?", options:["He made Solomon his son king over Israel","He retired to Hebron","He divided the kingdom","He anointed a new high priest"], a:0, ref:"1 Chronicles 23:1",verse:"So when David was old and full of days, he made Solomon his son king over Israel.", insight:"Old and full of days, David's last act was to secure the succession; finish by handing on the work."},
{q:"Whom did David gather together?", options:["All the princes of Israel, with the priests and the Levites","The armies of Judah","The elders of Gibeon","The singers only"], a:0, ref:"1 Chronicles 23:2",verse:"And he gathered together all the princes of Israel, with the priests and the Levites.", insight:"Princes, priests, and Levites together; the whole house of God organized in one assembly."},
{q:"From what age were the Levites first numbered?", options:["Thirty years and upward","Twenty years and upward","Twenty-five years and upward","Forty years and upward"], a:0, ref:"1 Chronicles 23:3",verse:"Now the Levites were numbered from the age of thirty years and upward: and their number by their polls, man by man, was thirty and eight thousand.", insight:"Thirty years and upward; mature strength for the heavy service of the house."},
{q:"How many Levites were numbered man by man?", options:["Thirty and eight thousand","Twenty and four thousand","Twelve thousand","Seventy thousand"], a:0, ref:"1 Chronicles 23:3",verse:"Now the Levites were numbered from the age of thirty years and upward: and their number by their polls, man by man, was thirty and eight thousand.", insight:"Thirty-eight thousand, counted by name; God knows His servants one by one."},
{q:"How many Levites were to set forward the work of the house of the LORD?", options:["Twenty and four thousand","Six thousand","Four thousand","Twelve thousand"], a:0, ref:"1 Chronicles 23:4",verse:"Of which, twenty and four thousand were to set forward the work of the house of the LORD; and six thousand were officers and judges:", insight:"Twenty-four thousand to set forward the work; the majority were given to the labor itself."},
{q:"How many Levites were officers and judges?", options:["Six thousand","Twenty and four thousand","Four thousand","Two thousand"], a:0, ref:"1 Chronicles 23:4",verse:"Of which, twenty and four thousand were to set forward the work of the house of the LORD; and six thousand were officers and judges:", insight:"Six thousand for judgment; worship and justice serve in the same house."},
{q:"How many were porters, and how many praised with instruments?", options:["Four thousand porters, and four thousand praised the LORD","Six thousand porters, and four thousand praised","Four thousand porters, and six thousand praised","Two thousand of each"], a:0, ref:"1 Chronicles 23:5",verse:"Moreover four thousand were porters; and four thousand praised the LORD with the instruments which I made, said David, to praise therewith.", insight:"Porters at the gates, singers with instruments; every post in God's house is a calling."},
{q:"Into whose courses did David divide the Levites?", options:["The sons of Levi: Gershon, Kohath, and Merari","The sons of Aaron only","The twelve tribes","The families of Judah"], a:0, ref:"1 Chronicles 23:6",verse:"And David divided them into courses among the sons of Levi, namely, Gershon, Kohath, and Merari.", insight:"Gershon, Kohath, and Merari; order in worship begins with knowing your family."},
{q:"Who were the sons of Amram?", options:["Aaron and Moses","Gershon and Merari","Nadab and Abihu","Eleazar and Ithamar"], a:0, ref:"1 Chronicles 23:13",verse:"The sons of Amram; Aaron and Moses: and Aaron was separated, that he should sanctify the most holy things, he and his sons for ever, to burn incense before the LORD, to minister unto him, and to bless in his name for ever.", insight:"Aaron and Moses, brothers in one house; the priest and the prophet grew up together."},
{q:"Why was Aaron separated from his brethren?", options:["To sanctify the most holy things, and to burn incense before the LORD","To lead the armies of Israel","To judge the people","To build the temple"], a:0, ref:"1 Chronicles 23:13",verse:"The sons of Amram; Aaron and Moses: and Aaron was separated, that he should sanctify the most holy things, he and his sons for ever, to burn incense before the LORD, to minister unto him, and to bless in his name for ever.", insight:"Separated to sanctify the most holy things; some are set apart not for privilege but for nearness."},
{q:"How is Moses described in this chapter?", options:["Moses the man of God","Moses the king of Israel","Moses the high priest","Moses the warrior"], a:0, ref:"1 Chronicles 23:14",verse:"Now concerning Moses the man of God, his sons were named of the tribe of Levi.", insight:"'Moses the man of God'; the greatest title in Scripture is simply belonging to Him."},
{q:"Who were the sons of Moses?", options:["Gershom and Eliezer","Nadab and Abihu","Shebuel and Rehabiah","Mahli and Mushi"], a:0, ref:"1 Chronicles 23:15",verse:"The sons of Moses were, Gershom, and Eliezer.", insight:"Gershom and Eliezer; the lawgiver's sons served as Levites, not as princes."},
{q:"What became of Eleazar's daughters?", options:["Their brethren the sons of Kish took them","They served as singers","They married the sons of Aaron","They remained unmarried"], a:0, ref:"1 Chronicles 23:22",verse:"And Eleazar died, and had no sons, but daughters: and their brethren the sons of Kish took them.", insight:"Eleazar died sonless, but his daughters were not forgotten; God keeps the lines that seem to end."},
{q:"From what age did the Levites do the work of the house of the LORD?", options:["Twenty years and upward","Thirty years and upward","Twenty-five years and upward","Forty years and upward"], a:0, ref:"1 Chronicles 23:24",verse:"These were the sons of Levi after the house of their fathers; even the chief of the fathers, as they were counted by number of names by their polls, that did the work for the service of the house of the LORD, from the age of twenty years and upward.", insight:"Twenty years and upward; when the burden lightened, younger hands could join the work."},
{q:"Why would the Levites dwell in Jerusalem for ever?", options:["The LORD God of Israel had given rest unto his people","David had conquered all enemies","The ark had been hidden","The temple was finished"], a:0, ref:"1 Chronicles 23:25",verse:"For David said, The LORD God of Israel hath given rest unto his people, that they may dwell in Jerusalem for ever:", insight:"God had given rest; settled worship flows from settled peace."},
{q:"What change came for the Levites?", options:["They shall no more carry the tabernacle, nor any vessels of it","They would no longer sing","They would serve only at feasts","They would carry the ark alone"], a:0, ref:"1 Chronicles 23:26",verse:"And also unto the Levites; they shall no more carry the tabernacle, nor any vessels of it for the service thereof.", insight:"No more carrying the tabernacle; the wandering days were ending, and service took a new shape."},
{q:"What was the Levites' office?", options:["To wait on the sons of Aaron for the service of the house of the LORD","To offer the sacrifices themselves","To rule over Israel","To guard the treasury"], a:0, ref:"1 Chronicles 23:28",verse:"Because their office was to wait on the sons of Aaron for the service of the house of the LORD, in the courts, and in the chambers, and in the purifying of all holy things, and the work of the service of the house of God;", insight:"To wait on the sons of Aaron; greatness in God's house is measured by faithful assistance."},
{q:"When were the Levites to stand and praise?", options:["Every morning to thank and praise the LORD, and likewise at even","Only on the sabbath","At the new moons only","When the ark moved"], a:0, ref:"1 Chronicles 23:30",verse:"And to stand every morning to thank and praise the LORD, and likewise at even;", insight:"Morning and evening, every day; gratitude is not an occasion but a rhythm."},
{q:"On which occasions were burnt sacrifices offered continually?", options:["In the sabbaths, in the new moons, and on the set feasts","At harvest and vintage only","When the king commanded","At the jubilee alone"], a:0, ref:"1 Chronicles 23:31",verse:"And to offer all burnt sacrifices unto the LORD in the sabbaths, in the new moons, and on the set feasts, by number, according to the order commanded unto them, continually before the LORD:", insight:"Sabbaths, new moons, set feasts; the calendar itself was tuned to worship."},
{q:"What three charges were the Levites to keep?", options:["The charge of the tabernacle, the charge of the holy place, and the charge of the sons of Aaron","The charge of the gates, the treasury, and the army","The charge of the singers, the porters, and the judges","The charge of the ark, the altar, and the people"], a:0, ref:"1 Chronicles 23:32",verse:"And that they should keep the charge of the tabernacle of the congregation, and the charge of the holy place, and the charge of the sons of Aaron their brethren, in the service of the house of the LORD.", insight:"Three charges, one service; faithfulness in small trusts upholds the whole house."}
 ]},
{n:24, name:"The Priestly Courses",
 seal:{ref:"1 Chronicles 24:19",verse:"These were the orderings of them in their service to come into the house of the LORD, according to their manner, under Aaron their father, as the LORD God of Israel had commanded him."},
 facts:[
  "Did you know the eighth priestly course was Abijah, the very course of Zacharias, the father of John the Baptist, centuries later (1 Chronicles 24:10; Luke 1:5)?",
  "Did you know the priests were divided into twenty-four courses by lot, so that no family could claim the best turn of service for itself (1 Chronicles 24:5, 18)?",
  "Did you know Nadab and Abihu, Aaron's eldest sons, died childless, so the priesthood passed through the younger lines of Eleazar and Ithamar (1 Chronicles 24:2)?"
 ],
 questions:[
{q:"Who were the sons of Aaron?", options:["Nadab, and Abihu, Eleazar, and Ithamar","Gershon, Kohath, and Merari","Zadok and Ahimelech","Joab and Abishai"], a:0, ref:"1 Chronicles 24:1",verse:"Now these are the divisions of the sons of Aaron. The sons of Aaron; Nadab, and Abihu, Eleazar, and Ithamar.", insight:"Four sons, two lines; God's plan for the priesthood ran through the survivors."},
{q:"What happened to Nadab and Abihu?", options:["They died before their father, and had no children","They became kings over Israel","They led the Levites in song","They were carried captive"], a:0, ref:"1 Chronicles 24:2",verse:"But Nadab and Abihu died before their father, and had no children: therefore Eleazar and Ithamar executed the priest’s office.", insight:"The eldest died childless; being firstborn is no guarantee of continuance."},
{q:"Who then executed the priest's office?", options:["Eleazar and Ithamar","Nadab and Abihu","Zadok and Abiathar","Moses and Aaron"], a:0, ref:"1 Chronicles 24:2",verse:"But Nadab and Abihu died before their father, and had no children: therefore Eleazar and Ithamar executed the priest’s office.", insight:"Eleazar and Ithamar; God keeps His work going through the ones who remain."},
{q:"Who helped David distribute the priests?", options:["Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar","Nathan and Gad","Joab and Abishai","Asaph and Heman"], a:0, ref:"1 Chronicles 24:3",verse:"And David distributed them, both Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, according to their offices in their service.", insight:"A priest from each line; both families were honored in the ordering."},
{q:"How many chief men were found of Eleazar, and how many of Ithamar?", options:["Sixteen of Eleazar, and eight of Ithamar","Twelve of each","Eight of Eleazar, and sixteen of Ithamar","Twenty-four of each"], a:0, ref:"1 Chronicles 24:4",verse:"And there were more chief men found of the sons of Eleazar than of the sons of Ithamar; and thus were they divided. Among the sons of Eleazar there were sixteen chief men of the house of their fathers, and eight among the sons of Ithamar according to the house of their fathers.", insight:"Sixteen and eight, two to one; God distributes gifts unevenly and orders them fairly."},
{q:"How were the priests divided?", options:["By lot, one sort with another","By the king's favor","By age, eldest first","By their wealth"], a:0, ref:"1 Chronicles 24:5",verse:"Thus were they divided by lot, one sort with another; for the governors of the sanctuary, and governors of the house of God, were of the sons of Eleazar, and of the sons of Ithamar.", insight:"By lot; when men cast lots, God casts the deciding vote."},
{q:"Who wrote down the divisions?", options:["Shemaiah the son of Nethaneel the scribe, one of the Levites","Zadok the priest","Gad the seer","Ahimelech"], a:0, ref:"1 Chronicles 24:6",verse:"And Shemaiah the son of Nethaneel the scribe, one of the Levites, wrote them before the king, and the princes, and Zadok the priest, and Ahimelech the son of Abiathar, and before the chief of the fathers of the priests and Levites: one principal household being taken for Eleazar, and one taken for Ithamar.", insight:"A Levite scribe kept the record; God's order is worth writing down."},
{q:"How were the lots balanced between the two lines?", options:["One principal household taken for Eleazar, and one taken for Ithamar","All the lots went to Eleazar","The king chose for Ithamar","The elders voted"], a:0, ref:"1 Chronicles 24:6",verse:"And Shemaiah the son of Nethaneel the scribe, one of the Levites, wrote them before the king, and the princes, and Zadok the priest, and Ahimelech the son of Abiathar, and before the chief of the fathers of the priests and Levites: one principal household being taken for Eleazar, and one taken for Ithamar.", insight:"One for Eleazar, one for Ithamar; fairness was built into the very casting."},
{q:"Which houses drew the first and second lots?", options:["Jehoiarib first, Jedaiah second","Harim first, Seorim second","Abijah first, Maaziah second","Eleazar first, Ithamar second"], a:0, ref:"1 Chronicles 24:7",verse:"Now the first lot came forth to Jehoiarib, the second to Jedaiah,", insight:"Jehoiarib first; even the first place came by lot, not by claim."},
{q:"Which houses drew the third and fourth lots?", options:["Harim third, Seorim fourth","Jehoiarib third, Jedaiah fourth","Malchijah third, Mijamin fourth","Hakkoz third, Abijah fourth"], a:0, ref:"1 Chronicles 24:8",verse:"The third to Harim, the fourth to Seorim,", insight:"Each course in its turn; no family served twice while another waited."},
{q:"Which course drew the eighth lot?", options:["Abijah","Hakkoz","Jeshua","Shecaniah"], a:0, ref:"1 Chronicles 24:10",verse:"The seventh to Hakkoz, the eighth to Abijah,", insight:"Abijah, the eighth; centuries later, Zacharias of this course would hear of John's birth."},
{q:"Which course drew the last lot, the four and twentieth?", options:["Maaziah","Delaiah","Jachin","Gamul"], a:0, ref:"1 Chronicles 24:18",verse:"The three and twentieth to Delaiah, the four and twentieth to Maaziah.", insight:"Maaziah last; the last lot was cast with the same care as the first."},
{q:"How many priestly courses were there in all?", options:["Four and twenty","Twelve","Sixteen","Thirty"], a:0, ref:"1 Chronicles 24:18",verse:"The three and twentieth to Delaiah, the four and twentieth to Maaziah.", insight:"Twenty-four courses; a full round of service, year after year."},
{q:"In what order were the priests to come into the house of the LORD?", options:["According to their manner, under Aaron their father, as the LORD God of Israel had commanded him","Whenever the king called them","By their own choosing","Only at the great feasts"], a:0, ref:"1 Chronicles 24:19",verse:"These were the orderings of them in their service to come into the house of the LORD, according to their manner, under Aaron their father, as the LORD God of Israel had commanded him.", insight:"Under Aaron their father, as the LORD commanded; order in worship is obedience, not preference."},
{q:"Who is named of the sons of Amram among the rest of Levi?", options:["Shubael; of the sons of Shubael, Jehdeiah","Moses and Aaron","Gershom and Eliezer","Mahli and Mushi"], a:0, ref:"1 Chronicles 24:20",verse:"And the rest of the sons of Levi were these: Of the sons of Amram; Shubael: of the sons of Shubael; Jehdeiah.", insight:"Shubael and Jehdeiah; even the lesser lines are named and ordered."},
{q:"Name the sons of Hebron in their order.", options:["Jeriah the first, Amariah the second, Jahaziel the third, Jekameam the fourth","Amariah first, Jeriah second","Jekameam first, Jeriah last","Jahaziel first, Amariah second"], a:0, ref:"1 Chronicles 24:23",verse:"And the sons of Hebron; Jeriah the first, Amariah the second, Jahaziel the third, Jekameam the fourth.", insight:"First, second, third, fourth; God numbers the servants, not just the service."},
{q:"Who were the sons of Merari?", options:["Mahli and Mushi; the sons of Jaaziah, Beno","Eleazar and Kish","Mahli, Eder, and Jerimoth","Shubael and Jehdeiah"], a:0, ref:"1 Chronicles 24:26",verse:"The sons of Merari were Mahli and Mushi: the sons of Jaaziah; Beno.", insight:"Merari's sons kept their place; every family had its charge in the house."},
{q:"What is said of Eleazar of Mahli?", options:["He had no sons","He became high priest","He led the singers","He was carried captive"], a:0, ref:"1 Chronicles 24:28",verse:"Of Mahli came Eleazar, who had no sons.", insight:"He had no sons; some lines end, yet the work of God goes on."},
{q:"Who was the son of Kish?", options:["Jerahmeel","Eleazar","Mahli","Beno"], a:0, ref:"1 Chronicles 24:29",verse:"Concerning Kish: the son of Kish was Jerahmeel.", insight:"Jerahmeel, son of Kish; the record keeps even one name from fading."},
{q:"Where did the rest of the Levites cast their lots?", options:["Over against their brethren the sons of Aaron, in the presence of David the king","In the tabernacle at Gibeon","Before the ark alone","In the field of battle"], a:0, ref:"1 Chronicles 24:31",verse:"These likewise cast lots over against their brethren the sons of Aaron in the presence of David the king, and Zadok, and Ahimelech, and the chief of the fathers of the priests and Levites, even the principal fathers over against their younger brethren.", insight:"Over against their brethren, before the king; the Levites' order matched the priests', lot for lot."}
 ]},
{n:25, name:"The Singers' Courses",
 seal:{ref:"1 Chronicles 25:1",verse:"Moreover David and the captains of the host separated to the service of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with harps, with psalteries, and with cymbals: and the number of the workmen according to their service was:"},
 facts:[
  "Did you know temple music was called prophesying? The singers were separated 'to prophesy with harps, with psalteries, and with cymbals' (1 Chronicles 25:1).",
  "Did you know the twenty-four courses of twelve singers each add up to exactly two hundred fourscore and eight, matching the total given in the chapter (1 Chronicles 25:7, 31)?",
  "Did you know the lots were cast 'ward against ward, as well the small as the great, the teacher as the scholar,' so that rank decided nothing (1 Chronicles 25:8)?"
 ],
 questions:[
{q:"Whom did David and the captains of the host separate to the service of song?", options:["The sons of Asaph, and of Heman, and of Jeduthun","The sons of Aaron","The sons of Levi in general","The captains of the host"], a:0, ref:"1 Chronicles 25:1",verse:"Moreover David and the captains of the host separated to the service of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with harps, with psalteries, and with cymbals: and the number of the workmen according to their service was:", insight:"Three fathers of music; God appoints leaders for the song as He does for the sword."},
{q:"How many were instructed in the songs of the LORD?", options:["Two hundred fourscore and eight","One hundred and twenty","Seventy","Twelve"], a:0, ref:"1 Chronicles 25:7",verse:"So the number of them, with their brethren that were instructed in the songs of the LORD, even all that were cunning, was two hundred fourscore and eight.", insight:"Two hundred eighty-eight trained voices; God loves skill offered in His service."},
{q:"Who were the sons of Asaph?", options:["Zaccur, Joseph, Nethaniah, and Asarelah","Gedaliah, Zeri, and Jeshaiah","Bukkiah and Mattaniah","Shimei and Azareel"], a:0, ref:"1 Chronicles 25:2",verse:"Of the sons of Asaph; Zaccur, and Joseph, and Nethaniah, and Asarelah, the sons of Asaph under the hands of Asaph, which prophesied according to the order of the king.", insight:"Four sons under Asaph; the psalmist's house became a school of worship."},
{q:"Under whose hands did Asaph's sons prophesy, and by whose order?", options:["Under the hands of Asaph, according to the order of the king","Under the hands of David alone","By the order of the priests","Under no direction"], a:0, ref:"1 Chronicles 25:2",verse:"Of the sons of Asaph; Zaccur, and Joseph, and Nethaniah, and Asarelah, the sons of Asaph under the hands of Asaph, which prophesied according to the order of the king.", insight:"Under Asaph's hands, by the king's order; worship thrives under both skill and authority."},
{q:"How many sons did Jeduthun have?", options:["Six","Four","Fourteen","Twelve"], a:0, ref:"1 Chronicles 25:3",verse:"Of Jeduthun: the sons of Jeduthun; Gedaliah, and Zeri, and Jeshaiah, Hashabiah, and Mattithiah, six, under the hands of their father Jeduthun, who prophesied with a harp, to give thanks and to praise the LORD.", insight:"Six sons; a whole family tuned to the praise of God."},
{q:"What did Jeduthun do with his harp?", options:["Prophesied, to give thanks and to praise the LORD","Played for the king's table","Taught the young singers","Sounded the jubilee"], a:0, ref:"1 Chronicles 25:3",verse:"Of Jeduthun: the sons of Jeduthun; Gedaliah, and Zeri, and Jeshaiah, Hashabiah, and Mattithiah, six, under the hands of their father Jeduthun, who prophesied with a harp, to give thanks and to praise the LORD.", insight:"To give thanks and to praise; the harp's highest use is gratitude."},
{q:"How many sons of Heman are listed?", options:["Fourteen","Six","Four","Twelve"], a:0, ref:"1 Chronicles 25:4",verse:"Of Heman: the sons of Heman; Bukkiah, Mattaniah, Uzziel, Shebuel, and Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, and Romamti-ezer, Joshbekashah, Mallothi, Hothir, and Mahazioth:", insight:"Fourteen sons; God multiplied the seer's house into a choir."},
{q:"What was Heman called?", options:["The king's seer in the words of God, to lift up the horn","The chief of the porters","The king's scribe","The captain of the guard"], a:0, ref:"1 Chronicles 25:5",verse:"All these were the sons of Heman the king’s seer in the words of God, to lift up the horn. And God gave to Heman fourteen sons and three daughters.", insight:"The king's seer; the musician was also a prophet, lifting up the horn of praise."},
{q:"How many sons and daughters did God give Heman?", options:["Fourteen sons and three daughters","Six sons and two daughters","Twelve sons","Four sons"], a:0, ref:"1 Chronicles 25:5",verse:"All these were the sons of Heman the king’s seer in the words of God, to lift up the horn. And God gave to Heman fourteen sons and three daughters.", insight:"Fourteen sons and three daughters; large families were counted among God's gifts."},
{q:"Under whose hands were all the singers for song in the house of the LORD?", options:["Under the hands of their father","Under the hands of the king","Under the hands of the priests","Under no man's hands"], a:0, ref:"1 Chronicles 25:6",verse:"All these were under the hands of their father for song in the house of the LORD, with cymbals, psalteries, and harps, for the service of the house of God, according to the king’s order to Asaph, Jeduthun, and Heman.", insight:"Under their father's hands; the family was the first choir school."},
{q:"By whose order did the three choirs serve?", options:["The king's order to Asaph, Jeduthun, and Heman","The priests' order","The people's vote","The prophets' command"], a:0, ref:"1 Chronicles 25:6",verse:"All these were under the hands of their father for song in the house of the LORD, with cymbals, psalteries, and harps, for the service of the house of God, according to the king’s order to Asaph, Jeduthun, and Heman.", insight:"By the king's order; David organized praise as carefully as he organized war."},
{q:"How many cunning singers were there in all?", options:["Two hundred fourscore and eight","Two hundred","Three hundred","One hundred and forty-four"], a:0, ref:"1 Chronicles 25:7",verse:"So the number of them, with their brethren that were instructed in the songs of the LORD, even all that were cunning, was two hundred fourscore and eight.", insight:"Two hundred eighty-eight skilled singers; excellence in worship is worth counting."},
{q:"How were the lots cast for the singers?", options:["Ward against ward, as well the small as the great, the teacher as the scholar","The eldest first, the youngest last","The king chose each course","The fathers drew for their sons"], a:0, ref:"1 Chronicles 25:8",verse:"And they cast lots, ward against ward, as well the small as the great, the teacher as the scholar.", insight:"Small as great, teacher as scholar; before God, the lot levels every rank."},
{q:"To whom did the first lot come?", options:["Asaph to Joseph","Gedaliah","Zaccur","Bukkiah"], a:0, ref:"1 Chronicles 25:9",verse:"Now the first lot came forth for Asaph to Joseph: the second to Gedaliah, who with his brethren and sons were twelve:", insight:"Asaph to Joseph first; the father's house led the singers' order."},
{q:"How many were in each course?", options:["Twelve: he, his sons, and his brethren","Six","Twenty-four","Thirty"], a:0, ref:"1 Chronicles 25:9",verse:"Now the first lot came forth for Asaph to Joseph: the second to Gedaliah, who with his brethren and sons were twelve:", insight:"Twelve in each course; every band of singers was a family-sized fellowship."},
{q:"To whom did the fourth lot come?", options:["Izri","Zaccur","Nethaniah","Bukkiah"], a:0, ref:"1 Chronicles 25:11",verse:"The fourth to Izri, he, his sons, and his brethren, were twelve:", insight:"Izri fourth; each name in the order was remembered and written."},
{q:"To whom did the sixth lot come?", options:["Bukkiah","Jesharelah","Jeshaiah","Mattaniah"], a:0, ref:"1 Chronicles 25:13",verse:"The sixth to Bukkiah, he, his sons, and his brethren, were twelve:", insight:"Bukkiah sixth, of Heman's house; the seer's sons took their turn like the rest."},
{q:"To whom did the fourteenth lot come?", options:["Mattithiah","Jeremoth","Hananiah","Joshbekashah"], a:0, ref:"1 Chronicles 25:21",verse:"The fourteenth to Mattithiah, he, his sons, and his brethren, were twelve:", insight:"Mattithiah fourteenth, of Jeduthun's line; every course had its appointed season."},
{q:"To whom did the twentieth lot come?", options:["Eliathah","Hanani","Mallothi","Hothir"], a:0, ref:"1 Chronicles 25:27",verse:"The twentieth to Eliathah, he, his sons, and his brethren, were twelve:", insight:"Eliathah twentieth; the order ran its full course without favor."},
{q:"Which was the last of the four and twenty lots?", options:["Romamti-ezer","Mahazioth","Giddalti","Hothir"], a:0, ref:"1 Chronicles 25:31",verse:"The four and twentieth to Romamti-ezer, he, his sons, and his brethren, were twelve.", insight:"Romamti-ezer last; twenty-four courses, twelve singers each, two hundred eighty-eight voices strong."}
 ]}
]);